	defaultReactiveOptions,
	mutatingArrayMethods,
	parentSourceCache,
	proxyRefs,
	proxySources,
	reactiveRawObjects,
	readonlyReactiveOptionsKey,
	rootProxyCache,
	sourcedProxyCache,
	type CachedParentSource
