sources.write-micro.mjs:
import {writeFile} from 'node:fs/promises';
import {performance} from 'node:perf_hooks';
const ids=['baseline','descriptor','version'];
const modules=Object.fromEntries(await Promise.all(ids.map(async id=>[id,await import(`./runtime-${id}.mjs`)])));
const evidence={iterations:20000,warmupRounds:4,rounds:30,scenarios:{}};
for(const scenario of ['direct','publish','rollback-batch','optimistic-journal']){
 const samples=Object.fromEntries(ids.map(id=>[id,[]]));
 for(let round=-4;round<30;round++) for(const id of (round%2?[...ids].reverse():ids)){
  const r=modules[id]; const state=r.reactive({a:0,b:0});
  const start=performance.now();
  for(let i=0;i<20000;i++){
   const update=()=>{state.a=i+1;state.b=i+1;};
   if(scenario==='direct')update();
   else if(scenario==='publish')r.publishBatch(update);
   else if(scenario==='rollback-batch')r.batch(update);
   else r.captureReactiveMutations(update).discard();
  }
  const duration=performance.now()-start;
  if(state.a!==20000||state.b!==20000)throw Error('incorrect result');
  if(round>=0)samples[id].push(duration);
  await new Promise(resolve=>setImmediate(resolve));
 }
 evidence.scenarios[scenario]=samples;
 console.log(scenario,Object.fromEntries(Object.entries(samples).map(([id,x])=>[id,x.reduce((s,v)=>s+v,0)/x.length])));
}
await writeFile('.tmp/reactivity-hypotheses/write-micro.json',JSON.stringify(evidence,null,2));

