import type { Dep, Reaction } from './types.js';

const deps = new WeakMap<object, Map<PropertyKey, Dep>>();
const depObservationHooks = new WeakMap<object, Map<PropertyKey, DependencyObservationHooks>>();
const reactionStack: Reaction[] = [];
/** Owns old memberships until a rerun has collected its replacement dependency set. */
type TrackingPass = { reaction: Reaction; previous: Dep[]; seen: Set<Dep> };

/** Contains only synchronous reruns; popped passes cannot retain disposed reactions. */
const trackingPasses: TrackingPass[] = [];
const trackingPauseFloors: number[] = [];
const pendingObservationTransitions: Array<() => void> = [];
let publishingObservationTransitions = false;

/** Identifies one target/key dependency without exposing its mutable subscriber set. */
export type ReactiveDependency = Readonly<{ target: object; key: PropertyKey }>;

/** Receives the first-observer and last-observer transitions for a dependency source. */
export type DependencyObservationHooks = Readonly<{
	onObserved(): void;
	onUnobserved(): void;
}>;

/** Records that the active reaction depends on a target/key pair. */
export function track(target: object, key: PropertyKey): boolean {
	const pauseFloor = trackingPauseFloors[trackingPauseFloors.length - 1];
	if (pauseFloor !== undefined && reactionStack.length <= pauseFloor) return false;
	const reaction = reactionStack[reactionStack.length - 1];
	if (!reaction) return false;
	linkReaction(reaction, target, key);
	return true;
}

/** Registers lifecycle hooks for the observer count of one dependency source. */
export function registerDependencyObservationHooks(
	target: object,
	key: PropertyKey,
	hooks: DependencyObservationHooks
): () => void {
	let targetHooks = depObservationHooks.get(target);
	if (!targetHooks) depObservationHooks.set(target, (targetHooks = new Map()));
	targetHooks.set(key, hooks);
	return () => {
		const current = depObservationHooks.get(target);
		if (current?.get(key) !== hooks) return;
		current.delete(key);
		if (!current.size) depObservationHooks.delete(target);
	};
}

/** Adds a reaction to one dependency while preserving observer-count transitions. */
export function linkReaction(reaction: Reaction, target: object, key: PropertyKey): void {
	linkReactionToDependency(reaction, getDep(target, key));
}

/** Adds a reaction to an existing dependency set while preserving observer-count transitions. */
export function linkReactionToDependency(reaction: Reaction, dep: Dep): void {
	const subscribers = dep.subscribers;
	const pass = trackingPasses[trackingPasses.length - 1];
	const collecting = pass?.reaction === reaction;
	if (subscribers === reaction || (subscribers instanceof Set && subscribers.has(reaction))) {
		if (collecting && !pass.seen.has(dep)) {
			pass.seen.add(dep);
			reaction.deps.push(dep);
		}
		return;
	}
	if (collecting) pass.seen.add(dep);
	const wasEmpty = subscribers === undefined;
	dep.subscribers =
		subscribers === undefined
			? reaction
			: subscribers instanceof Set
				? subscribers.add(reaction)
				: new Set([subscribers, reaction]);
	reaction.deps.push(dep);
	if (wasEmpty)
		publishObservationTransition(depObservationHooks.get(dep.target)?.get(dep.key)?.onObserved);
}

/** Returns immutable target/key descriptors for a reaction's current dependencies. */
export function reactionDependencies(reaction: Reaction): ReactiveDependency[] {
	return reaction.deps;
}

/** Returns the dependency set for a target/key pair, creating it on first use. */
export function getDep(target: object, key: PropertyKey): Dep {
	let targetDeps = deps.get(target);
	if (!targetDeps) deps.set(target, (targetDeps = new Map()));
	let dep = targetDeps.get(key);
	if (!dep) {
		dep = { target, key };
		targetDeps.set(key, dep);
	}
	return dep;
}

/** Removes a reaction from all dependency sets it currently belongs to. */
export function cleanupReaction(reaction: Reaction): void {
	for (const pass of trackingPasses)
		if (pass.reaction === reaction) {
			for (const dep of pass.previous) detachDependency(reaction, dep);
			pass.previous = [];
		}
	for (const dep of reaction.deps) detachDependency(reaction, dep);
	reaction.deps.length = 0;
}

/** Removes a single membership and publishes a real last-observer transition. */
function detachDependency(reaction: Reaction, dep: Dep): void {
	const subscribers = dep.subscribers;
	if (subscribers === reaction) dep.subscribers = undefined;
	else if (subscribers instanceof Set && subscribers.delete(reaction)) {
		if (subscribers.size === 1) dep.subscribers = subscribers.values().next().value;
		else if (subscribers.size === 0) dep.subscribers = undefined;
	} else return;
	if (dep.subscribers === undefined) releaseEmptyDependency(dep);
}

/** Schedules one stable snapshot of the reactions subscribed to a dependency. */
export function scheduleDependencyReactions(target: object, key: PropertyKey): void {
	const dep = deps.get(target)?.get(key);
	const subscribers = dep?.subscribers;
	if (subscribers instanceof Set) {
		for (const reaction of [...subscribers])
			if (observesDuringTracking(reaction, dep!)) reaction.schedule();
	} else if (subscribers && observesDuringTracking(subscribers, dep!)) subscribers.schedule();
}

/** Schedules subscribers for an atomic trigger collection through the coalescing scheduler. */
export function scheduleTriggeredReactions(triggers: Map<object, Set<PropertyKey>>): void {
	if (!triggers.size) return;
	const reactions = new Set<Reaction>();
	for (const [target, keys] of triggers) {
		const targetDeps = deps.get(target);
		if (!targetDeps) continue;
		for (const key of keys) {
			const dep = targetDeps.get(key);
			const subscribers = dep?.subscribers;
			if (subscribers instanceof Set) {
				for (const reaction of subscribers)
					if (observesDuringTracking(reaction, dep!)) reactions.add(reaction);
			} else if (subscribers && observesDuringTracking(subscribers, dep!))
				reactions.add(subscribers);
		}
	}
	// A custom scheduler may run synchronously and replace its own watcher. Snapshotting every
	// affected reaction before scheduling prevents the replacement from joining this publication;
	// deduplication also preserves one atomic notification when several changed keys share it.
	for (const reaction of reactions) reaction.schedule();
}

/** Old memberships remain retained until exit but cannot invalidate an unread branch during execution. */
function observesDuringTracking(reaction: Reaction, dep: Dep): boolean {
	for (let i = trackingPasses.length - 1; i >= 0; i--) {
		const pass = trackingPasses[i]!;
		if (pass.reaction === reaction) return pass.seen.has(dep);
	}
	return true;
}

/** Runs a function while collecting all reactive reads into the supplied reaction. */
export function runTracked(reaction: Reaction, fn: () => void): void {
	// Initial collection has no memberships to reconcile. Computed values also clear their
	// source subscriptions before evaluation, so they take this allocation-free path.
	const pass = reaction.deps.length
		? { reaction, previous: reaction.deps, seen: new Set<Dep>() }
		: undefined;
	if (pass) {
		reaction.deps = [];
		trackingPasses.push(pass);
	}
	reactionStack.push(reaction);
	try {
		fn();
	} finally {
		reactionStack.pop();
		if (pass) {
			trackingPasses.pop();
			for (const dep of pass.previous) if (!pass.seen.has(dep)) detachDependency(reaction, dep);
		}
		if (!reaction.active) cleanupReaction(reaction);
	}
}

/** Runs a function without linking its reads to the currently active reaction. */
export function peek<T>(fn: () => T): T {
	trackingPauseFloors.push(reactionStack.length);
	try {
		return fn();
	} finally {
		trackingPauseFloors.pop();
	}
}

function releaseEmptyDependency(dep: Dep): void {
	publishObservationTransition(depObservationHooks.get(dep.target)?.get(dep.key)?.onUnobserved);
	const targetDeps = deps.get(dep.target);
	if (targetDeps?.get(dep.key) === dep) targetDeps.delete(dep.key);
	if (targetDeps && !targetDeps.size) deps.delete(dep.target);
}

function publishObservationTransition(transition: (() => void) | undefined): void {
	if (!transition) return;
	pendingObservationTransitions.push(transition);
	if (publishingObservationTransitions) return;
	publishingObservationTransitions = true;
	try {
		while (pendingObservationTransitions.length) pendingObservationTransitions.pop()!();
	} finally {
		publishingObservationTransitions = false;
	}
}

sources.retention.mjs:
import {writeFile} from 'node:fs/promises';
const id=process.argv[2];
const r=await import(`./runtime-${id}.mjs`);
const tick=()=>new Promise(resolve=>setImmediate(resolve));
async function collect(){for(let i=0;i<4;i++){await tick();global.gc();}await tick();}
class TrackingRetentionPayload{constructor(){this.bytes=new Uint8Array(8192);}}
const state=r.reactive({value:0,selected:true});
let reads=0;
function install(refs,mode){
 const payload=new TrackingRetentionPayload();refs.push(new WeakRef(payload));
 const scope=r.createEffectScope();
 r.withEffectScope(scope,()=>r.watch(()=>{
  reads+=payload.bytes.length;
  if(state.selected)void state.value;
  else if(mode==='stop-during-run'){scope.stop();void state.value;}
  else if(mode==='throw-during-run')throw Error('expected');
 },undefined,{onError:()=>{}}));
 return ()=>scope.stop();
}
function exercise(){
 const refs=[];const stops=[];
 for(let i=0;i<500;i++)stops.push(install(refs,['normal','stop-during-run','throw-during-run'][i%3]));
 for(let i=0;i<8;i++){state.value++;r.flushSync();}
 state.selected=false;r.flushSync();
 for(const stop of stops)stop();r.flushSync();
 state.selected=true;
 return refs;
}
const evidence={id,checkpoints:[],collected:0,uncollected:0};
for(let round=0;round<8;round++){
 let refs=exercise();
 await collect();
 const uncollected=refs.filter(ref=>ref.deref()).length;
 evidence.collected+=refs.length-uncollected;evidence.uncollected+=uncollected;
 refs=[];await collect();
 evidence.checkpoints.push({round,heapUsed:process.memoryUsage().heapUsed,uncollected});
}
const holder=r.reactive({child:{value:0}});const dropped=[];
const stop=r.watch(()=>void holder.child.value);
for(let i=0;i<2000;i++){dropped.push(new WeakRef(r.unwrap(holder.child)));holder.child={value:i+1};r.flushSync();}
await collect();evidence.droppedDependenciesStillReachable=dropped.filter(ref=>ref.deref()).length;stop();
evidence.reads=reads;
await writeFile(`.tmp/reactivity-hypotheses/retention-${id}.json`,JSON.stringify(evidence,null,2));console.log(evidence);
if(evidence.uncollected||evidence.droppedDependenciesStillReachable)process.exitCode=1;

sources.micro-mitigated.mjs:
import {writeFile} from 'node:fs/promises';
import {performance} from 'node:perf_hooks';
const variants=['baseline','tracking-corrected','tracking-mitigated'];const modules={};for(const id of variants)modules[id]=await import(`./runtime-${id}.mjs`);
const evidence={};
for(const scenario of ['stable','branching','batched-writes']){
 const samples=Object.fromEntries(variants.map(id=>[id,[]]));
 for(let round=-4;round<20;round++)for(const id of (round%2?[...variants].reverse():variants)){
 const r=modules[id];const state=r.reactive({a:0,b:1,flip:false});let observed=0;
 const stops=Array.from({length:scenario==='batched-writes'?1:100},()=>r.watch(()=>{observed+=state.a+(scenario==='branching'&&state.flip?state.b:0);}));
 const start=performance.now();for(let i=0;i<2000;i++){
 if(scenario==='batched-writes')r.batch(()=>{state.a++;state.b++;});
 else {state.a++;if(scenario==='branching')state.flip=!state.flip;}
 r.flushSync();
 }
 const ms=performance.now()-start;for(const stop of stops)stop();if(!observed)throw Error('missing observation');if(round>=0)samples[id].push(ms);await new Promise(resolve=>setImmediate(resolve));
 }
 evidence[scenario]=samples;console.log(scenario,Object.fromEntries(Object.entries(samples).map(([id,x])=>[id,x.reduce((s,v)=>s+v,0)/x.length])));
}
await writeFile('.tmp/reactivity-hypotheses/micro-mitigated.json',JSON.stringify(evidence,null,2));

